import ifcopenshell
import ifcopenshell.geom
import numpy as np
import math

# Path to the IFC model
model_path = "/Users/sylvainhellin/GitHub/4_phd/ifcAnswerEngineV3/src/experiment/bim_models/dental_clinic/arc.ifc"

# Load the IFC file
ifc_file = ifcopenshell.open(model_path)

# Helper function to obtain a centroid for an IFC element
def get_centroid(entity):
    """Return the centroid of the entity as a NumPy array (model units)."""
    try:
        settings = ifcopenshell.geom.settings()
        # Disable subtraction of openings for speed; not needed for centroid
        settings.set(settings.DISABLE_OPENING_SUBTRACTIONS, True)
        shape = ifcopenshell.geom.create_shape(settings, entity)
        verts = np.array(shape.geometry.verts).reshape(-1, 3)
        if verts.size == 0:
            raise ValueError("No vertices")
        return verts.mean(axis=0)
    except Exception:
        # Fallback to the placement location (if available)
        try:
            placement = entity.ObjectPlacement
            while placement and placement.is_a("IfcLocalPlacement"):
                rel = placement.RelativePlacement
                if rel and rel.is_a("IfcAxis2Placement3D"):
                    loc = rel.Location
                    return np.array([loc.Coordinates[0], loc.Coordinates[1], loc.Coordinates[2]])
                placement = placement.PlacementRelTo
        except Exception:
            pass
    return None

# 1. Find the treatment room named "1E12" (case‑insensitive search in IfcSpace names)
room = None
for space in ifc_file.by_type("IfcSpace"):
    name = getattr(space, "Name", "")
    if name and "1e12" in name.lower():
        room = space
        break

if room is None:
    answer_text = ("The information is not available in the BIM model. "
                   "No space matching the name '1E12' could be found.")
else:
    room_centroid = get_centroid(room)
    if room_centroid is None:
        answer_text = ("The information is not available in the BIM model. "
                       "The location of treatment room 1E12 could not be determined.")
    else:
        # 2. Find doors that are likely emergency exits (name contains "emergency" or "exit")
        exit_doors = []
        for door in ifc_file.by_type("IfcDoor"):
            dname = getattr(door, "Name", "")
            if dname and (("emergency" in dname.lower()) or ("exit" in dname.lower())):
                exit_doors.append(door)

        if not exit_doors:
            answer_text = ("The information is not available in the BIM model. "
                           "No door identified as an emergency exit could be found.")
        else:
            # 3. Compute distances and find the nearest exit
            min_dist = None
            nearest_exit = None
            for door in exit_doors:
                door_centroid = get_centroid(door)
                if door_centroid is None:
                    continue
                dist = np.linalg.norm(room_centroid - door_centroid)
                if (min_dist is None) or (dist < min_dist):
                    min_dist = dist
                    nearest_exit = door

            if min_dist is None:
                answer_text = ("The information is not available in the BIM model. "
                               "Could not compute centroids for the emergency exits.")
            else:
                # Round distance to two decimal places; assume model units are metres
                distance_str = f"{min_dist:.2f}"
                exit_name = getattr(nearest_exit, "Name", "Unnamed Exit")
                answer_text = (f"The nearest emergency exit to treatment room 1E12 is \"{exit_name}\" "
                               f"at a distance of {distance_str} units (model units, typically metres).")

