import ifcopenshell
import math

# Path to the IFC file (provided by the user)
model_path = "/Users/sylvainhellin/GitHub/4_phd/ifcAnswerEngineV3/src/experiment/bim_models/dental_clinic/arc.ifc"

# Load the IFC model
ifc_file = ifcopenshell.open(model_path)

def get_absolute_placement_coords(element):
    """Return (x, y, z) of the element's ObjectPlacement resolved to the site origin."""
    def resolve(pl):
        if pl is None:
            return (0.0, 0.0, 0.0)
        if pl.is_a("IfcLocalPlacement"):
            rel = pl.RelativePlacement
            if rel and rel.is_a("IfcAxis2Placement3D"):
                loc = rel.Location
                x, y, z = loc.Coordinates
            else:
                x = y = z = 0.0
            parent = pl.PlacementRelTo
            px, py, pz = resolve(parent)
            return (x + px, y + py, z + pz)
        # Unexpected placement type – treat as origin
        return (0.0, 0.0, 0.0)
    return resolve(element.ObjectPlacement)

# -------------------------------------------------
# 1. Find the target treatment room (IfcSpace)
target_name = "treatment room 1e23".lower()
target_space = None
for space in ifc_file.by_type("IfcSpace"):
    name = getattr(space, "Name", "")
    if name and target_name in name.lower():
        target_space = space
        break

if target_space is None:
    answer = ("The information is not available in the BIM model: "
              "no space whose name contains 'treatment room 1E23' was found.")
    final_answer({"answer": answer})
    raise SystemExit

room_coords = get_absolute_placement_coords(target_space)

# -------------------------------------------------
# 2. Find all emergency exit doors (IfcDoor)
emergency_doors = []
for door in ifc_file.by_type("IfcDoor"):
    name = getattr(door, "Name", "")
    if name and "emergency" in name.lower():
        emergency_doors.append(door)

# If no doors were found by name, try a simple property check for a property named "EmergencyExit"
if not emergency_doors:
    for door in ifc_file.by_type("IfcDoor"):
        for rel in getattr(door, "IsDefinedBy", []):
            if rel.is_a("IfcRelDefinesByProperties"):
                pset = rel.RelatingPropertyDefinition
                if pset.is_a("IfcPropertySet"):
                    for prop in getattr(pset, "HasProperties", []):
                        if prop.Name.lower() in ("emergencyexit", "emergency_exit", "emergency"):
                            emergency_doors.append(door)
                            break

if not emergency_doors:
    answer = ("The information is not available in the BIM model: "
              "no emergency exit doors could be identified.")
    final_answer({"answer": answer})
    raise SystemExit

# -------------------------------------------------
# 3. Compute distances
def euclidean(p1, p2):
    return math.sqrt((p1[0]-p2[0])**2 + (p1[1]-p2[1])**2 + (p1[2]-p2[2])**2)

min_dist = None
nearest_door = None
for door in emergency_doors:
    d_coords = get_absolute_placement_coords(door)
    dist = euclidean(room_coords, d_coords)
    if (min_dist is None) or (dist < min_dist):
        min_dist = dist
        nearest_door = door

# -------------------------------------------------
# 4. Prepare answer (model units are typically metres)
if min_dist is not None:
    answer = (f"The shortest distance from treatment room 1E23 to an emergency exit "
              f"is approximately {min_dist:.2f} metres.")
else:
    answer = ("The information is not available in the BIM model: "
              "distance could not be calculated.")

final_answer({"answer": answer})
